alter table public.progress_photo_reactions drop constraint progress_photo_reactions_emoji_check;
alter table public.progress_photo_reactions add constraint progress_reaction_emoji_catalog foreign key(emoji) references private.progress_emoji(emoji);

create table public.progress_comments (
 id uuid primary key default gen_random_uuid(),
 photo_id uuid not null references public.progress_photos(id) on delete cascade,
 user_id uuid not null references public.profiles(id) on delete cascade,
 body text not null check(length(btrim(body)) between 1 and 1000),
 created_at timestamptz not null default clock_timestamp()
);
create index progress_comments_photo_page on public.progress_comments(photo_id,created_at desc,id desc);
alter table public.progress_comments enable row level security;
revoke all on public.progress_comments from public,anon,authenticated;
grant select,insert,delete on public.progress_comments to authenticated;
create policy "Photo viewers read comments" on public.progress_comments for select to authenticated
 using(exists(select 1 from public.progress_photos p where p.id=photo_id));
create policy "Photo viewers post own comments" on public.progress_comments for insert to authenticated
 with check(user_id=(select auth.uid()) and exists(select 1 from public.progress_photos p where p.id=photo_id));
create policy "Users remove own comments" on public.progress_comments for delete to authenticated using(user_id=(select auth.uid()));
create table private.progress_comment_rate(user_id uuid not null references public.profiles(id) on delete cascade,posted_at timestamptz not null);
create index progress_comment_rate_user on private.progress_comment_rate(user_id,posted_at desc);
revoke all on private.progress_comment_rate from public,anon,authenticated;
create function private.guard_progress_comment() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or new.user_id is distinct from auth.uid() or not exists(
 select 1 from public.progress_photos p where p.id=new.photo_id and (p.user_id=auth.uid() or private.is_friend(p.user_id))) then
 raise exception 'This picture is not available.' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(new.user_id::text,441));
 if exists(select 1 from public.progress_comments c where c.id=new.id and c.user_id=new.user_id) then return null; end if;
 delete from private.progress_comment_rate where user_id=new.user_id and posted_at<now()-interval '1 day';
 if (select count(*) from private.progress_comment_rate where user_id=new.user_id and posted_at>now()-interval '1 minute')>=20
 or (select count(*) from private.progress_comment_rate where user_id=new.user_id)>=500 then
 raise exception 'Wait a moment before posting more comments.' using errcode='54000'; end if;
 insert into private.progress_comment_rate values(new.user_id,clock_timestamp());
 new.body:=btrim(new.body);new.created_at:=clock_timestamp();return new;
end $$;
revoke all on function private.guard_progress_comment() from public,anon,authenticated;
create trigger guard_progress_comment before insert on public.progress_comments for each row execute function private.guard_progress_comment();
create function public.progress_photo_comments(target_photo uuid,before_at timestamptz default null,before_id uuid default null)
returns table(id uuid,user_id uuid,username text,body text,created_at timestamptz)
language sql stable security definer set search_path='' as $$
 select c.id,c.user_id,p.username,c.body,c.created_at from public.progress_comments c join public.profiles p on p.id=c.user_id
 where c.photo_id=target_photo and auth.uid() is not null and exists(select 1 from public.progress_photos f where f.id=target_photo and(f.user_id=auth.uid() or private.is_friend(f.user_id)))
 and (before_at is null or (c.created_at,c.id)<(before_at,before_id)) order by c.created_at desc,c.id desc limit 30
$$;
revoke all on function public.progress_photo_comments(uuid,timestamptz,uuid) from public,anon;
grant execute on function public.progress_photo_comments(uuid,timestamptz,uuid) to authenticated;
notify pgrst,'reload schema';
